{
  "name": "vite-plugin-aipanel",
  "version": "1.3.14",
  "description": "Embed OpenCode Web UI in your Vite dev server for real-time code modification and preview",
  "type": "module",
  "main": "lib/index.cjs",
  "module": "es/index.mjs",
  "types": "es/index.d.ts",
  "files": [
    "es",
    "lib"
  ],
  "exports": {
    ".": {
      "types": "./es/index.d.ts",
      "import": "./es/index.mjs",
      "require": "./lib/index.cjs"
    }
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  },
  "keywords": [
    "vite",
    "plugin",
    "opencode",
    "ai",
    "assistant",
    "chat",
    "hmr",
    "real-time",
    "code-modification"
  ],
  "author": "",
  "license": "MIT",
  "dependencies": {
    "@aipanel/core": "1.3.14",
    "@aipanel/provider-opencode": "1.3.14",
    "@code-inspector/core": "^2.0.9",
    "@vue/devtools-kit": "^8.0.0",
    "@vue/language-server": "^3.3.7",
    "chrome-devtools-mcp": "1.12.0",
    "execa": "^9.6.1",
    "picomatch": "^4.0.2",
    "typescript-language-server": "^5.3.0",
    "unplugin-vue-inspector": "^3.0.0"
  },
  "peerDependencies": {
    "@aipanel/provider-deepseek": "1.3.14",
    "vite": ">=5.0.0"
  },
  "peerDependenciesMeta": {
    "@aipanel/provider-deepseek": {
      "optional": true
    }
  },
  "devDependencies": {
    "@aipanel/client": "1.3.14",
    "@types/picomatch": "^4.0.0",
    "sharp": "^0.34.5"
  },
  "scripts": {
    "build": "node scripts/sync-official-meta.mjs && pagoda-cli build && vite build -c vite.client.config.ts",
    "typecheck": "tsc -p tsconfig.declaration.json --noEmit",
    "test": "vitest run",
    "test:coverage": "vitest run --coverage"
  }
}
